	restarted.waitForReadyLine()
	restartURL := "http://" + serveRuntimeAPIListenerFromOutput(t, restarted.outputString())
	status, response = sendInboundAdmissionSupportedRequest(t, restartURL, "telegram", []byte(`{"update_id":902,"message":{"message_id":902,"from":{"id":7},"chat":{"id":42,"type":"private"},"text":"after restart"}}`), map[string]string{"X-Telegram-Bot-Api-Secret-Token": "telegram-secret"})
